import { useState, lazy, Suspense } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import { Skeleton } from '@/components/ui/skeleton'
import type { GearItem } from '@/types/database'

// Lazy load the heavy form component
const AddGearForm = lazy(() => import('./AddGearForm').then(m => ({ default: m.AddGearForm })))

interface AddGearFormWrapperProps {
  onAdd: (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => void
  onCancel?: () => void
  simplified?: boolean
  isOpen?: boolean
}

export function AddGearFormWrapper({ 
  onAdd, 
  onCancel, 
  simplified = false,
  isOpen = true
}: AddGearFormWrapperProps) {
  const [loading, setLoading] = useState(false)

  const handleAdd = async (gear: Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    setLoading(true)
    try {
      await onAdd(gear)
      // Don't close automatically - let parent handle it
    } finally {
      setLoading(false)
    }
  }

  return (
    <MobileFormDrawer
      isOpen={isOpen}
      onClose={onCancel || (() => {})}
      title="Add Gear"
      primaryAction={
        onCancel ? {
          label: 'Add Gear',
          onClick: () => {
            // Trigger form submission using data attribute selector
            const form = document.querySelector('form[data-gear-form]') as HTMLFormElement
            if (form) {
              form.requestSubmit()
            }
          },
          loading
        } : undefined
      }
      secondaryAction={
        onCancel ? {
          label: 'Cancel',
          onClick: onCancel
        } : undefined
      }
    >
      <div className="p-6">
        <Suspense fallback={
          <div className="space-y-4">
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-10 w-full" />
            <Skeleton className="h-20 w-full" />
          </div>
        }>
          <AddGearForm
            onAdd={handleAdd}
            onCancel={onCancel}
            simplified={simplified}
            standalone={false}
          />
        </Suspense>
      </div>
    </MobileFormDrawer>
  )
}

