import { test, expect } from '@playwright/test'

// End-to-end user flows for gear management
test.describe('Gear Management Flows', () => {
  test.beforeEach(async ({ page }) => {
    // Skip if no Supabase credentials
    if (!process.env.VITE_SUPABASE_URL || !process.env.VITE_SUPABASE_ANON_KEY) {
      test.skip('Skipping gear management flow tests - no Supabase credentials available')
    }

    await page.goto('/gear')
    await page.waitForLoadState('domcontentloaded')
    await page.waitForSelector('main, [role="main"]', { timeout: 10000 })

    // Ensure authentication worked
    if (page.url().includes('/login')) {
      throw new Error('Authentication failed - redirected to login page')
    }
  })

  test.describe('Add Gear Flow', () => {
    test('complete add gear workflow', async ({ page }) => {
      // 1. Open add gear form
      const addButton = await findAddButton(page)

      // Try regular click first, then force click if DevTools interfere
      try {
        await addButton.click({ timeout: 3000 })
      } catch (error) {
        console.log('Regular click failed, using force click due to DevTools overlay')
        await addButton.click({ force: true, timeout: 3000 })
      }

      // 2. Fill out gear form
      const form = await findGearForm(page)
      await fillGearForm(page, form, {
        name: 'Test Backpack',
        weight: '1200',
        brand: 'TestBrand',
        category: 'Pack'
      })

      // 3. Submit form - button is in the dialog, not the form
      const submitButton = page.locator('[role="dialog"] button:has-text("Add Gear")')
      await submitButton.click({ timeout: 3000 })

      // 4. Verify gear was added (look for it in the list)
      await page.waitForTimeout(1000)
      const gearList = page.locator('text="Test Backpack"')
      await expect(gearList.first()).toBeVisible({ timeout: 3000 })
    })

    test('handles form errors gracefully', async ({ page }) => {
      const addButton = await findAddButton(page)

      // Try regular click first, then force click if DevTools interfere
      try {
        await addButton.click({ timeout: 3000 })
      } catch (error) {
        console.log('Regular click failed, using force click due to DevTools overlay')
        await addButton.click({ force: true, timeout: 3000 })
      }

      const form = await findGearForm(page)

      // Wait for lazy-loaded form to fully render
      await page.waitForTimeout(1000)

      // Submit form with empty required field
      // Leave description field empty (required field) - using correct field ID
      const descriptionField = form.locator('#description').first()
      await descriptionField.waitFor({ state: 'visible', timeout: 3000 })
      await descriptionField.clear()

      // Submit button is in the dialog footer
      const submitButton = page.locator('[role="dialog"] button:has-text("Add Gear")')
      await submitButton.click({ timeout: 3000 })

      // Form should still be open (not submitted due to validation)
      await page.waitForTimeout(500)
      const dialog = page.locator('[role="dialog"][aria-modal="true"]')
      await expect(dialog).toBeVisible({ timeout: 2000 })

      // Description field should still be empty (validation prevented submission)
      const descriptionFieldAfter = form.locator('#description').first()
      const value = await descriptionFieldAfter.inputValue()
      expect(value).toBe('')
    })
  })

  test.describe('Navigation Flow', () => {
    test('user can navigate through app sections', async ({ page }) => {
      // Should be on gear page
      expect(page.url()).toContain('/gear')

      // Look for navigation - could be in header, sidebar, or nav menu
      const navSelectors = [
        'nav',
        'header',
        '[role="navigation"]',
        'a[href="/dashboard"], a[href="/gear"], a[href="/lists"]'
      ]

      let foundNav = false
      for (const selector of navSelectors) {
        const navElement = page.locator(selector).first()
        if (await navElement.count() > 0) {
          foundNav = true
          break
        }
      }

      // At minimum, should have a header with app name/logo
      if (!foundNav) {
        const header = page.locator('h1, [role="banner"], .app-header')
        foundNav = await header.count() > 0
      }

      expect(foundNav).toBe(true)
    })

    test('maintains authentication across page navigation', async ({ page }) => {
      // Start on gear page (authenticated)
      expect(page.url()).toContain('/gear')

      // Try navigating to root/dashboard
      await page.goto('/dashboard')
      await page.waitForLoadState('domcontentloaded')

      // Should not be redirected to login
      await page.waitForTimeout(2000)
      expect(page.url()).not.toContain('/login')

      // Should show authenticated content - check for user dropdown button
      // User dropdown location depends on viewport size
      const viewport = page.viewportSize()
      let userButton

      if (viewport && viewport.width >= 1024) {
        // Desktop: user button in sidebar
        userButton = page.locator('aside button').filter({ has: page.locator('svg.h-4.w-4') })
      } else {
        // Mobile/Tablet: user button in header
        userButton = page.locator('header button').filter({ has: page.locator('svg') })
      }

      // Verify user button exists (indicates authenticated state)
      expect(await userButton.count()).toBeGreaterThan(0)
    })
  })

  test.describe('Search and Filter Flow', () => {
    test('user can search for gear items', async ({ page }) => {
      // Look for search functionality
      const searchBox = page.locator('input[placeholder*="search" i], input[type="search"]')

      if (await searchBox.count() === 0) {
        test.skip('Search functionality not found')
      }

      // Perform search
      await searchBox.first().fill('backpack')
      await page.waitForTimeout(1000)

      // Results should update (this is a basic test - results may be empty)
      // The important thing is that search doesn't crash the app
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })

    test('user can filter by category', async ({ page }) => {
      // Look for category filter button or dropdown
      const categorySelectors = [
        'button:has-text("Category")',
        'button:has-text("Filter")',
        '[aria-label*="category" i]',
        '[data-testid*="category" i]',
        'select[name="category"]'
      ]

      let categoryFilter = null
      for (const selector of categorySelectors) {
        const element = page.locator(selector)
        if (await element.count() > 0) {
          // Check if it's visible or can be scrolled into view
          const isVisible = await element.first().isVisible()
          if (isVisible) {
            categoryFilter = element.first()
            break
          }
        }
      }

      if (!categoryFilter) {
        test.skip('Category filter not implemented yet')
        return
      }

      // Click the filter
      await categoryFilter.scrollIntoViewIfNeeded()
      await categoryFilter.click()
      await page.waitForTimeout(500)

      // Verify the page is still functional
      const body = page.locator('body')
      await expect(body).toBeVisible()
    })
  })
})

// Helper functions
async function findAddButton(page) {
  // Wait for page to fully load
  await page.waitForLoadState('networkidle')

  // First try to find the floating action button by its specific styling
  const fabButton = page.locator('button.rounded-full.shadow-lg').filter({
    has: page.locator('svg')
  }).first()

  if (await fabButton.count() > 0) {
    return fabButton
  }

  // Fallback: Look for any button containing a plus icon
  const plusButton = page.locator('button').filter({
    has: page.locator('svg')  // Has an SVG icon
  }).filter({
    hasText: /^$/ // No text content (icon-only)
  })

  if (await plusButton.count() > 0) {
    return plusButton.last() // Get the last one (likely the FAB)
  }

  // Final fallback: look for button with "Add" text if no gear items exist
  const addFirstButton = page.locator('button:has-text("Add First Item")')
  if (await addFirstButton.count() > 0) {
    return addFirstButton
  }

  throw new Error('Add button not found')
}

async function findGearForm(page) {
  // Wait a bit for lazy loading and animations/transitions
  await page.waitForTimeout(500)

  // Wait for the dialog to appear with more specific selectors
  const dialogSelectors = [
    '[role="dialog"][aria-modal="true"]',
    '[role="dialog"]',
    '.mobile-form-drawer',
    '[aria-labelledby="drawer-title"]'
  ]

  let dialog = null
  for (const selector of dialogSelectors) {
    try {
      // Reduced timeout for faster feedback
      await page.waitForSelector(selector, { state: 'visible', timeout: 2000 })
      dialog = page.locator(selector).first()
      if (await dialog.isVisible()) {
        break
      }
    } catch (e) {
      continue // Try next selector
    }
  }

  if (!dialog) {
    throw new Error('Gear form dialog not found with any selector')
  }

  // Wait for the form to be fully loaded inside the dialog
  await page.waitForTimeout(200)

  // Return the form inside the dialog, or the dialog itself
  const form = dialog.locator('form').first()
  if (await form.count() > 0) {
    return form
  }
  return dialog
}

async function fillGearForm(page, form, data) {
  // Fill by specific input identifiers
  if (data.name) {
    const nameInput = form.locator('input#name, input[placeholder*="Backpack" i]').first()
    await nameInput.waitFor({ state: 'visible' })
    await nameInput.fill(data.name)
  }

  if (data.weight) {
    const weightInput = form.locator('input#weight, input[placeholder="Weight"]').first()
    await weightInput.waitFor({ state: 'visible' })
    await weightInput.fill(data.weight)
  }

  if (data.brand) {
    const brandInput = form.locator('input#brand, input[placeholder*="brand" i], input[placeholder*="Gossamer" i]').first()
    if (await brandInput.count() > 0) {
      await brandInput.fill(data.brand)
    }
  }

  if (data.category) {
    // Category might be a select or custom dropdown
    const categorySelect = form.locator('#category, select, button[role="combobox"]').first()
    if (await categorySelect.count() > 0) {
      await categorySelect.click()
      await page.waitForTimeout(500)
      // Look for option in dropdown or select
      const option = page.locator(`[role="option"]:has-text("${data.category}"), option:has-text("${data.category}")`)
      if (await option.count() > 0) {
        await option.first().click()
      }
    }
  }
}
